import{_ as e,o as l,c as i,O as o}from"./chunks/framework.db831a78.js";const p=JSON.parse('{"title":"Java 基础","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/01-Java基础.md","filePath":"interview/后端/Java/01-Java基础.md","lastUpdated":null}'),t={name:"interview/后端/Java/01-Java基础.md"};function r(n,a,s,c,d,h){return l(),i("div",null,a[0]||(a[0]=[o(`<h1 id="java-基础" tabindex="-1">Java 基础 <a class="header-anchor" href="#java-基础" aria-label="Permalink to &quot;Java 基础&quot;">​</a></h1><blockquote><p>常问等级：★★★ 高频必考 / ★★☆ 中频常见 / ★☆☆ 低频了解 深度标准：每个考点讲清「是什么 → 为什么 → 源码关键点 → 追问应对 → 易错点」，做到能扛住连续追问。</p></blockquote><hr><h2 id="基本数据类型和包装类区别、integer-缓存、自动装箱拆箱-★★★" tabindex="-1">基本数据类型和包装类区别、Integer 缓存、自动装箱拆箱 ★★★ <a class="header-anchor" href="#基本数据类型和包装类区别、integer-缓存、自动装箱拆箱-★★★" aria-label="Permalink to &quot;基本数据类型和包装类区别、Integer 缓存、自动装箱拆箱 ★★★&quot;">​</a></h2><h3 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><ul><li>8 种基本类型：byte(1) / short(2) / int(4) / long(8) / float(4) / double(8) / char(2) / boolean，对应包装类 Byte、Short、Integer、Long、Float、Double、Character、Boolean。</li><li>区别： <table><thead><tr><th>维度</th><th>基本类型</th><th>包装类</th></tr></thead><tbody><tr><td>存储</td><td>值，存栈</td><td>对象，存堆（引用在栈）</td></tr><tr><td>默认值</td><td>0 / false</td><td>null</td></tr><tr><td>泛型</td><td>不能用</td><td>可以用</td></tr><tr><td>性能</td><td>高</td><td>低（有对象头、装箱开销）</td></tr></tbody></table></li></ul><h3 id="为什么会有自动装箱拆箱" tabindex="-1">为什么会有自动装箱拆箱 <a class="header-anchor" href="#为什么会有自动装箱拆箱" aria-label="Permalink to &quot;为什么会有自动装箱拆箱&quot;">​</a></h3><ul><li>Java 集合、泛型只支持对象，基本类型要放进去必须先包装，为了书写方便编译器自动插入装箱/拆箱代码。</li></ul><h3 id="源码关键点" tabindex="-1">源码关键点 <a class="header-anchor" href="#源码关键点" aria-label="Permalink to &quot;源码关键点&quot;">​</a></h3><ul><li>装箱：编译器把 <code>Integer a = 100</code> 编译成 <code>Integer.valueOf(100)</code>。</li><li>拆箱：把 <code>int b = a</code> 编译成 <code>a.intValue()</code>。</li><li><code>Integer.valueOf(int)</code> 内部：<div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#F97583;">public</span><span style="color:#E1E4E8;"> </span><span style="color:#F97583;">static</span><span style="color:#E1E4E8;"> Integer </span><span style="color:#B392F0;">valueOf</span><span style="color:#E1E4E8;">(</span><span style="color:#F97583;">int</span><span style="color:#E1E4E8;"> i) {</span></span>
<span class="line"><span style="color:#E1E4E8;">    </span><span style="color:#F97583;">if</span><span style="color:#E1E4E8;"> (i </span><span style="color:#F97583;">&gt;=</span><span style="color:#E1E4E8;"> IntegerCache.low </span><span style="color:#F97583;">&amp;&amp;</span><span style="color:#E1E4E8;"> i </span><span style="color:#F97583;">&lt;=</span><span style="color:#E1E4E8;"> IntegerCache.high)</span></span>
<span class="line"><span style="color:#E1E4E8;">        </span><span style="color:#F97583;">return</span><span style="color:#E1E4E8;"> IntegerCache.cache[i </span><span style="color:#F97583;">+</span><span style="color:#E1E4E8;"> (</span><span style="color:#F97583;">-</span><span style="color:#E1E4E8;">IntegerCache.low)];</span></span>
<span class="line"><span style="color:#E1E4E8;">    </span><span style="color:#F97583;">return</span><span style="color:#E1E4E8;"> </span><span style="color:#F97583;">new</span><span style="color:#E1E4E8;"> </span><span style="color:#B392F0;">Integer</span><span style="color:#E1E4E8;">(i);</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#D73A49;">public</span><span style="color:#24292E;"> </span><span style="color:#D73A49;">static</span><span style="color:#24292E;"> Integer </span><span style="color:#6F42C1;">valueOf</span><span style="color:#24292E;">(</span><span style="color:#D73A49;">int</span><span style="color:#24292E;"> i) {</span></span>
<span class="line"><span style="color:#24292E;">    </span><span style="color:#D73A49;">if</span><span style="color:#24292E;"> (i </span><span style="color:#D73A49;">&gt;=</span><span style="color:#24292E;"> IntegerCache.low </span><span style="color:#D73A49;">&amp;&amp;</span><span style="color:#24292E;"> i </span><span style="color:#D73A49;">&lt;=</span><span style="color:#24292E;"> IntegerCache.high)</span></span>
<span class="line"><span style="color:#24292E;">        </span><span style="color:#D73A49;">return</span><span style="color:#24292E;"> IntegerCache.cache[i </span><span style="color:#D73A49;">+</span><span style="color:#24292E;"> (</span><span style="color:#D73A49;">-</span><span style="color:#24292E;">IntegerCache.low)];</span></span>
<span class="line"><span style="color:#24292E;">    </span><span style="color:#D73A49;">return</span><span style="color:#24292E;"> </span><span style="color:#D73A49;">new</span><span style="color:#24292E;"> </span><span style="color:#6F42C1;">Integer</span><span style="color:#24292E;">(i);</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div></li><li><code>IntegerCache</code> 默认缓存 <code>-128 ~ 127</code>，可通过 <code>-XX:AutoBoxCacheMax=&lt;size&gt;</code> 调大上限。</li></ul><h3 id="追问应对" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「<code>Integer a=100, b=100; a==b</code> 为什么是 true，128 是 false？」→ 100 在缓存内 <code>valueOf</code> 返回同一个缓存对象，所以 <code>==</code> 为 true；128 超出缓存，各自 <code>new Integer</code> 地址不同。</li><li>「<code>Integer</code> 之间比较应该用什么？」→ 用 <code>equals</code> 或先拆箱成 <code>int</code> 再 <code>==</code>，别用 <code>==</code> 直接比包装类。</li></ul><h3 id="易错点" tabindex="-1">易错点 <a class="header-anchor" href="#易错点" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li>循环里 <code>Integer sum = 0; for(...) sum += i;</code> 每次 <code>+=</code> 都会拆箱+装箱，产生大量临时对象；大循环用 <code>int</code>。</li><li><code>Long</code> 也有类似缓存（-128~127），<code>Long l1 = 100L</code> 走缓存。</li><li>三元运算符 <code>condition ? 1 : new Integer(2)</code> 两个分支类型不一致时会触发自动拆箱/装箱，可能 NPE。</li></ul><hr><h2 id="面向对象三大特性、抽象类和接口区别-★★★" tabindex="-1">面向对象三大特性、抽象类和接口区别 ★★★ <a class="header-anchor" href="#面向对象三大特性、抽象类和接口区别-★★★" aria-label="Permalink to &quot;面向对象三大特性、抽象类和接口区别 ★★★&quot;">​</a></h2><h3 id="是什么-1" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-1" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><ul><li>封装：把数据和操作数据的方法绑定，隐藏内部实现（private + 对外暴露 public getter/setter），只暴露必要接口。</li><li>继承：子类复用父类字段与方法，Java 单继承（一个类只能有一个直接父类）、多层继承。</li><li>多态：同一操作作用于不同对象产生不同行为。编译期多态 = 重载；运行期多态 = 重写 + 父类引用指向子类对象，方法调用在运行时动态分派。</li></ul><h3 id="为什么多态靠动态分派" tabindex="-1">为什么多态靠动态分派 <a class="header-anchor" href="#为什么多态靠动态分派" aria-label="Permalink to &quot;为什么多态靠动态分派&quot;">​</a></h3><ul><li>方法调用分静态分派（重载，编译期根据参数静态类型确定）和动态分派（重写，运行期根据对象实际类型确定）。JVM 用 invokevirtual 指令，先在常量池找到方法符号引用，运行时到实际对象类型的类的方法表中找实现。</li></ul><h3 id="抽象类-vs-接口-表格" tabindex="-1">抽象类 vs 接口（表格） <a class="header-anchor" href="#抽象类-vs-接口-表格" aria-label="Permalink to &quot;抽象类 vs 接口（表格）&quot;">​</a></h3><table><thead><tr><th>维度</th><th>抽象类</th><th>接口</th></tr></thead><tbody><tr><td>关键字</td><td>abstract class</td><td>interface</td></tr><tr><td>继承实现</td><td>单继承</td><td>多实现，接口间可多继承</td></tr><tr><td>成员</td><td>可有构造器、普通字段、具体方法、静态方法</td><td>常量 + 抽象方法；Java8 default/static，Java9 private</td></tr><tr><td>设计语义</td><td>is-a，抽取公共代码</td><td>can-do，定义能力契约</td></tr><tr><td>构造器</td><td>有</td><td>无</td></tr></tbody></table><h3 id="追问应对-1" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-1" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「接口为什么要有 default 方法？」→ 接口演进：给老接口加方法时，实现类不用全部被迫修改（如 <code>List.stream()</code>），同时保留实现灵活性。</li><li>「抽象类和接口怎么选？」→ 需要共享字段/构造器/非静态代码逻辑用抽象类；只定义能力、需要多实现用接口；优先接口（组合优于继承）。</li></ul><h3 id="易错点-1" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-1" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li>接口的字段默认 <code>public static final</code>（常量），方法默认 <code>public abstract</code>；Java8 default 方法必须写方法体。</li></ul><hr><h2 id="string、stringbuilder、stringbuffer-string-不可变-常量池-intern-★★★" tabindex="-1">String、StringBuilder、StringBuffer；String 不可变；常量池；intern() ★★★ <a class="header-anchor" href="#string、stringbuilder、stringbuffer-string-不可变-常量池-intern-★★★" aria-label="Permalink to &quot;String、StringBuilder、StringBuffer；String 不可变；常量池；intern() ★★★&quot;">​</a></h2><h3 id="string-为什么不可变" tabindex="-1">String 为什么不可变 <a class="header-anchor" href="#string-为什么不可变" aria-label="Permalink to &quot;String 为什么不可变&quot;">​</a></h3><ul><li>底层用 <code>private final byte[] value</code>（JDK9 起 char[] 改 byte[]，节省空间）+ 类本身 <code>final</code>。</li><li><code>final</code> 修饰 value 只保证引用不换对象，不保证数组内容不被改；真正不可变靠「类不提供修改 value 的 public 方法 + 所有修改操作都 new 新对象」。</li><li>好处：① 可安全共享（常量池）；② 可作 HashMap/HashSet 的 key（hash 不变）；③ 线程安全；④ 类加载器、安全机制依赖不可变 String。</li></ul><h3 id="三兄弟区别" tabindex="-1">三兄弟区别 <a class="header-anchor" href="#三兄弟区别" aria-label="Permalink to &quot;三兄弟区别&quot;">​</a></h3><ul><li>String 不可变；StringBuilder 可变、非线程安全（快）；StringBuffer 可变、方法加 synchronized（慢、线程安全）。</li></ul><h3 id="常量池与-intern" tabindex="-1">常量池与 intern() <a class="header-anchor" href="#常量池与-intern" aria-label="Permalink to &quot;常量池与 intern()&quot;">​</a></h3><ul><li>字符串常量池：JDK7 起从永久代移到堆中，存字符串字面量与 intern 结果。</li><li><code>intern()</code>：若池中已有 equals 相等的字符串，返回池内引用；否则把该字符串引用放入池并返回。</li><li>经典面试：<code>String s = new String(&quot;a&quot;)</code> 创建了几个对象？—— 字面量 &quot;a&quot; 一个（放常量池）+ new 的一个 = 2 个。</li></ul><h3 id="源码关键点-1" tabindex="-1">源码关键点 <a class="header-anchor" href="#源码关键点-1" aria-label="Permalink to &quot;源码关键点&quot;">​</a></h3><ul><li><code>&quot;a&quot; + &quot;b&quot;</code> 编译期常量折叠为 <code>&quot;ab&quot;</code>（字面量拼接直接优化）；含变量的 <code>&quot;a&quot; + b</code> 编译成 <code>new StringBuilder().append(&quot;a&quot;).append(b).toString()</code>。</li><li>JDK9 起 <code>+</code> 拼接编译为 <code>StringConcatFactory</code> 的 invokedynamic，性能更好。</li></ul><h3 id="追问应对-2" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-2" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么不用 <code>String</code> 做频繁拼接？」→ 每次 <code>+</code> 都 new 新对象，产生大量中间对象 + 常量池压力，用 StringBuilder。</li><li>「intern() 有性能问题吗？」→ JDK7 后常量池在堆，intern 可能让堆里对象无法回收，滥用会 OOM；JDK8 后有所改善，但仍不建议频繁 intern。</li></ul><h3 id="易错点-2" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-2" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li><code>new String(&quot;abc&quot;) == &quot;abc&quot;</code> 为 false（一个堆对象、一个常量池）。</li><li><code>StringBuilder</code> 默认容量 16，扩容为「旧容量*2 + 2」。</li></ul><hr><h2 id="arraylist-linkedlist-底层、扩容机制-★★★" tabindex="-1">ArrayList / LinkedList 底层、扩容机制 ★★★ <a class="header-anchor" href="#arraylist-linkedlist-底层、扩容机制-★★★" aria-label="Permalink to &quot;ArrayList / LinkedList 底层、扩容机制 ★★★&quot;">​</a></h2><h3 id="arraylist" tabindex="-1">ArrayList <a class="header-anchor" href="#arraylist" aria-label="Permalink to &quot;ArrayList&quot;">​</a></h3><ul><li>底层 <code>Object[] elementData</code>，随机访问 O(1)，增删（中间）O(n)（要移动元素）。</li><li>扩容（源码 <code>grow</code>）：默认初始容量 10（首次 add 时才真正分配），扩容为 <code>oldCapacity + (oldCapacity &gt;&gt; 1)</code> 即 1.5 倍，<code>Arrays.copyOf</code> 复制到新数组。</li><li>扩容本质是「新数组 + 拷贝」，代价高，若预知大小用 <code>new ArrayList&lt;&gt;(n)</code> 避免多次扩容。</li></ul><h3 id="linkedlist" tabindex="-1">LinkedList <a class="header-anchor" href="#linkedlist" aria-label="Permalink to &quot;LinkedList&quot;">​</a></h3><ul><li>底层双向链表，每个节点存 prev/next/item；头尾增删 O(1)，按索引访问 O(n)（要从头/尾遍历）。</li><li>额外维护前后指针，内存占用比 ArrayList 大。</li></ul><h3 id="为什么说-linkedlist-实际用得少" tabindex="-1">为什么说 LinkedList 实际用得少 <a class="header-anchor" href="#为什么说-linkedlist-实际用得少" aria-label="Permalink to &quot;为什么说 LinkedList 实际用得少&quot;">​</a></h3><ul><li>表面「中段插入快」，但插入前要先遍历定位（O(n)），整体并不比 ArrayList 快多少；且链表缓存不友好（内存不连续，无法利用 CPU 缓存）。多数场景 ArrayList 更优。</li></ul><h3 id="追问应对-3" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-3" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「ArrayList 是线程安全的吗？」→ 不是；并发用 <code>CopyOnWriteArrayList</code>（读多写少）或 <code>Collections.synchronizedList</code>。</li><li>「扩容为什么是 1.5 倍不是 2 倍？」→ 经验值，平衡空间浪费与扩容频率；1.5 倍能复用部分旧数组内存（偏移），2 倍不能。</li></ul><h3 id="易错点-3" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-3" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li><code>ArrayList</code> 的 <code>size()</code> 是元素个数，不是数组容量；<code>elementData.length</code> 才是容量。</li><li>用迭代器遍历时 <code>remove</code> 要用 <code>iterator.remove()</code>，直接 <code>list.remove()</code> 会 ConcurrentModificationException（见 fail-fast）。</li></ul><hr><h2 id="hashmap-底层原理-1-7-vs-1-8、红黑树、扩容-★★★" tabindex="-1">HashMap 底层原理（1.7 vs 1.8、红黑树、扩容）★★★ <a class="header-anchor" href="#hashmap-底层原理-1-7-vs-1-8、红黑树、扩容-★★★" aria-label="Permalink to &quot;HashMap 底层原理（1.7 vs 1.8、红黑树、扩容）★★★&quot;">​</a></h2><h3 id="数据结构" tabindex="-1">数据结构 <a class="header-anchor" href="#数据结构" aria-label="Permalink to &quot;数据结构&quot;">​</a></h3><ul><li>JDK1.7：数组 + 链表（Entry）。</li><li>JDK1.8：数组 + 链表 + 红黑树（Node/TreeNode），链表过长时树化，查询从 O(n) 降到 O(logn)。</li></ul><h3 id="为什么容量必须是-2-的幂" tabindex="-1">为什么容量必须是 2 的幂 <a class="header-anchor" href="#为什么容量必须是-2-的幂" aria-label="Permalink to &quot;为什么容量必须是 2 的幂&quot;">​</a></h3><ul><li>定位桶用 <code>(n - 1) &amp; hash</code>，等价 <code>hash % n</code>，位运算更快。</li><li>扩容迁移时：新位置只需看 <code>hash &amp; oldCap</code> 是否为 0，为 0 留在原位，为 1 移到 <code>原位 + oldCap</code>，无需重新计算 hash，这是 2 的幂的最大收益。</li></ul><h3 id="扰动函数为什么是-h-key-hashcode-h-16" tabindex="-1">扰动函数为什么是 <code>(h = key.hashCode()) ^ (h &gt;&gt;&gt; 16)</code> <a class="header-anchor" href="#扰动函数为什么是-h-key-hashcode-h-16" aria-label="Permalink to &quot;扰动函数为什么是 \`(h = key.hashCode()) ^ (h &gt;&gt;&gt; 16)\`&quot;">​</a></h3><ul><li>若直接用 hashCode 低几位做 <code>(n-1)&amp;hash</code>，高位不参与，分布不均。</li><li>右移 16 位让高 16 位与低 16 位异或，把高位特征混入低位，降低碰撞。</li></ul><h3 id="为什么链表阈值-8、退化-6" tabindex="-1">为什么链表阈值 8、退化 6 <a class="header-anchor" href="#为什么链表阈值-8、退化-6" aria-label="Permalink to &quot;为什么链表阈值 8、退化 6&quot;">​</a></h3><ul><li>桶中元素个数服从泊松分布，负载因子 0.75 时链表长度达 8 的概率约 6e-8，极小，用 8 树化是成本收益权衡（红黑树节点更大、更复杂）。</li><li>退化阈值 6 不是 7，留缓冲避免「反复树化/退化」抖动。</li></ul><h3 id="put-流程-putval-源码步骤" tabindex="-1">put 流程（putVal 源码步骤） <a class="header-anchor" href="#put-流程-putval-源码步骤" aria-label="Permalink to &quot;put 流程（putVal 源码步骤）&quot;">​</a></h3><ol><li>计算 <code>hash = (h = key.hashCode()) ^ (h &gt;&gt;&gt; 16)</code>。</li><li>数组为空先 <code>resize()</code>。</li><li>定位桶 <code>(n-1) &amp; hash</code>： <ul><li>桶空：直接放入。</li><li>桶是红黑树：走树插入。</li><li>桶是链表：遍历，key 相同覆盖 value；否则尾插；遍历中链表长度 ≥ 8 且数组 ≥ 64 时树化。</li></ul></li><li>插入后 <code>size++</code>，超过阈值 <code>capacity * loadFactor</code> 触发 <code>resize()</code>。</li></ol><h3 id="扩容-resize-过程" tabindex="-1">扩容 resize 过程 <a class="header-anchor" href="#扩容-resize-过程" aria-label="Permalink to &quot;扩容 resize 过程&quot;">​</a></h3><ul><li>容量翻倍（2 倍），新建数组，遍历旧数组每个桶，按 <code>hash &amp; oldCap</code> 拆成低位链、高位链；低位链留在原位，高位链移到 <code>原位+oldCap</code>；链表可能重新拆分，树可能退化为链表。</li></ul><h3 id="_1-7-头插法死循环" tabindex="-1">1.7 头插法死循环 <a class="header-anchor" href="#_1-7-头插法死循环" aria-label="Permalink to &quot;1.7 头插法死循环&quot;">​</a></h3><ul><li>1.7 扩容用头插法（新元素插头部），链表逆序；多线程同时扩容时，两个线程迁移互相指向形成环，<code>get</code> 时死循环。</li><li>1.8 改尾插法解决成环，但并发下仍有「丢数据」「数据覆盖」问题，所以并发场景必须用 ConcurrentHashMap。</li></ul><h3 id="追问应对-4" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-4" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「负载因子为什么 0.75？」→ 时间空间折中，太高碰撞多（链表变长查询慢），太低空间浪费。</li><li>「为什么不用 hash 取模？」→ 位运算更快 + 2 的幂扩容迁移优化。</li><li>「HashMap 的 key 为什么建议用 String/不可变对象？」→ hashCode 稳定，改 key 内容会导致哈希定位错乱。</li><li>「红黑树 vs AVL 树为什么用红黑树？」→ 红黑树牺牲部分平衡换更少旋转，插入删除更高效，查询 O(logn) 也够用。</li></ul><h3 id="易错点-4" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-4" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li>重写 equals 必须重写 hashCode（见下文契约），否则 HashMap 会 key 定位错误。</li><li>HashMap 允许一个 null key、多个 null value；Hashtable/ConcurrentHashMap 不允许 null。</li></ul><hr><h2 id="concurrenthashmap-1-7-和-1-8-实现区别-★★★" tabindex="-1">ConcurrentHashMap 1.7 和 1.8 实现区别 ★★★ <a class="header-anchor" href="#concurrenthashmap-1-7-和-1-8-实现区别-★★★" aria-label="Permalink to &quot;ConcurrentHashMap 1.7 和 1.8 实现区别 ★★★&quot;">​</a></h2><h3 id="_1-7-segment-分段锁" tabindex="-1">1.7：Segment 分段锁 <a class="header-anchor" href="#_1-7-segment-分段锁" aria-label="Permalink to &quot;1.7：Segment 分段锁&quot;">​</a></h3><ul><li>结构：Segment（继承 ReentrantLock）+ 每段一个 HashEntry 数组。</li><li>锁粒度：Segment 级别，不同 Segment 间可并发；并发度 = Segment 数量（默认 16，可调）。</li><li>put 需先定位 Segment 再加锁。</li></ul><h3 id="_1-8-synchronized-cas-桶级锁" tabindex="-1">1.8：synchronized + CAS 桶级锁 <a class="header-anchor" href="#_1-8-synchronized-cas-桶级锁" aria-label="Permalink to &quot;1.8：synchronized + CAS 桶级锁&quot;">​</a></h3><ul><li>结构：和 HashMap 一样「数组 + 链表 + 红黑树」，不再有 Segment。</li><li>写：对「单个桶的头节点」加 synchronized，粒度更细；空桶用 CAS 无锁写入（如 <code>casTabAt</code> 初始化、<code>tabAt</code> 读）。</li><li>读：完全无锁，因为 <code>Node.val</code> 和 <code>Node.next</code> 用 volatile 修饰，保证可见性。</li><li>扩容：多线程协助迁移（<code>ForwardingNode</code> 标记已迁移的桶），并发扩容。</li></ul><h3 id="为什么-1-8-更快" tabindex="-1">为什么 1.8 更快 <a class="header-anchor" href="#为什么-1-8-更快" aria-label="Permalink to &quot;为什么 1.8 更快&quot;">​</a></h3><ul><li>锁粒度从「段」细化到「桶」；读无锁；红黑树降低查询复杂度；synchronized 经 JDK1.6 锁升级优化后性能已很高。</li></ul><h3 id="追问应对-5" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-5" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「1.8 用 synchronized 而不是 ReentrantLock，为什么？」→ 锁升级优化后 synchronized 性能接近，且写法更简洁、JVM 层面可自动优化。</li><li>「ConcurrentHashMap 为什么不允许 null key/value？」→ 并发下 <code>get</code> 返回 null 无法区分「不存在」还是「存的是 null」，会歧义，故设计上禁止。</li></ul><h3 id="易错点-5" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-5" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li><code>size()</code> 在 1.8 用 <code>baseCount + CounterCell</code> 累加，非精确实时（弱一致）。</li><li>单机替代 Hashtable 首选 ConcurrentHashMap。</li></ul><hr><h2 id="hashtable-与-hashmap-对比-★★☆" tabindex="-1">Hashtable 与 HashMap 对比 ★★☆ <a class="header-anchor" href="#hashtable-与-hashmap-对比-★★☆" aria-label="Permalink to &quot;Hashtable 与 HashMap 对比 ★★☆&quot;">​</a></h2><ul><li>Hashtable 线程安全（方法级 synchronized）、不允许 null 键值；HashMap 非线程安全、允许一个 null key 多个 null value。</li><li>Hashtable 初始容量 11、扩容 <code>2n+1</code>（质数减少碰撞）；HashMap 初始 16、扩容 2 倍。</li><li>Hashtable 已被 ConcurrentHashMap 取代（后者分段/桶级锁，性能远高于方法级锁）。</li><li>追问：「HashMap 如何做到线程安全？」→ 用 ConcurrentHashMap 或 <code>Collections.synchronizedMap</code>（后者仍是方法级锁，性能差）。</li></ul><hr><h2 id="异常体系、受检-非受检-try-finally-try-with-resources-★★★" tabindex="-1">异常体系、受检/非受检；try-finally / try-with-resources ★★★ <a class="header-anchor" href="#异常体系、受检-非受检-try-finally-try-with-resources-★★★" aria-label="Permalink to &quot;异常体系、受检/非受检；try-finally / try-with-resources ★★★&quot;">​</a></h2><h3 id="体系" tabindex="-1">体系 <a class="header-anchor" href="#体系" aria-label="Permalink to &quot;体系&quot;">​</a></h3><ul><li>根 <code>Throwable</code> → <code>Error</code>（JVM 级错误，如 OOM、StackOverflowError，不可恢复，不捕获）和 <code>Exception</code>。</li><li>Exception 分： <ul><li>受检异常（checked）：编译期强制处理（try-catch 或 throws），如 IOException、SQLException。</li><li>非受检异常（unchecked）：RuntimeException 及其子类，如 NPE、IndexOutOfBoundsException、IllegalArgumentException，编译期不强制。</li></ul></li></ul><h3 id="为什么分受检-非受检" tabindex="-1">为什么分受检/非受检 <a class="header-anchor" href="#为什么分受检-非受检" aria-label="Permalink to &quot;为什么分受检/非受检&quot;">​</a></h3><ul><li>受检异常是「调用者能预判并恢复」的（文件不存在、网络失败），强制处理避免遗漏；非受检通常是「编程错误」（空指针、越界），应该靠修复代码而非捕获。</li></ul><h3 id="try-finally-与-try-with-resources" tabindex="-1">try-finally 与 try-with-resources <a class="header-anchor" href="#try-finally-与-try-with-resources" aria-label="Permalink to &quot;try-finally 与 try-with-resources&quot;">​</a></h3><ul><li>finally 总执行（除非 System.exit 或线程被 kill）；finally 中 return 会覆盖 try 的 return 值。</li><li>try-with-resources：资源实现 <code>AutoCloseable</code>，在 try 括号内声明，自动 close（编译后仍生成 finally close 代码），避免重复关闭，且 close 异常被压制（suppressed）。</li><li>JDK9 起允许 try 括号内用已有变量：<code>try (resource) {...}</code>。</li></ul><h3 id="追问应对-6" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-6" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「finally 一定能执行吗？」→ 不是，<code>System.exit(0)</code>、JVM 崩溃、守护线程中断等不会执行。</li><li>「catch 和 finally 都有 return，返回哪个？」→ finally 的 return 覆盖 catch 的 return（但不推荐，可读性差）。</li></ul><h3 id="易错点-6" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-6" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li><code>return</code> 在 finally 会吞掉 try 抛出的异常，导致异常丢失。</li><li>自定义业务异常建议继承 RuntimeException（避免全链路 throws 污染）。</li></ul><hr><h2 id="泛型原理、泛型擦除-通配符-extends-super-★★★" tabindex="-1">泛型原理、泛型擦除；通配符 ? / ? extends / ? super ★★★ <a class="header-anchor" href="#泛型原理、泛型擦除-通配符-extends-super-★★★" aria-label="Permalink to &quot;泛型原理、泛型擦除；通配符 ? / ? extends / ? super ★★★&quot;">​</a></h2><h3 id="泛型擦除" tabindex="-1">泛型擦除 <a class="header-anchor" href="#泛型擦除" aria-label="Permalink to &quot;泛型擦除&quot;">​</a></h3><ul><li>Java 泛型是编译期概念，编译时擦除类型参数： <ul><li>无边界的 <code>T</code> 擦除为 Object；</li><li>有上界的 <code>T extends Number</code> 擦除为 Number；</li><li>使用处插入强制类型转换（checkcast）。</li></ul></li><li>所以运行时 <code>List&lt;String&gt;</code> 与 <code>List&lt;Integer&gt;</code> 是同一个 Class（<code>ArrayList.class</code>），无法通过反射拿到泛型实参（除字段/方法签名上的泛型信息，那存在常量池 Signature 里）。</li></ul><h3 id="为什么擦除" tabindex="-1">为什么擦除 <a class="header-anchor" href="#为什么擦除" aria-label="Permalink to &quot;为什么擦除&quot;">​</a></h3><ul><li>为兼容 Java5 之前的旧代码（二进制兼容），泛型只是「编译期类型安全检查」，运行时不改变 JVM 字节码结构。</li></ul><h3 id="通配符" tabindex="-1">通配符 <a class="header-anchor" href="#通配符" aria-label="Permalink to &quot;通配符&quot;">​</a></h3><ul><li><code>?</code> 无限制通配符。</li><li><code>? extends T</code>（上界，协变）：只能读（取出来是 T），不能写（add 报错，除 null）——因为不知道具体子类型。</li><li><code>? super T</code>（下界，逆变）：可写 T，读出是 Object。</li><li>口诀 PECS：Producer Extends（生产数据用 extends），Consumer Super（消费数据用 super）。</li></ul><h3 id="追问应对-7" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-7" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「<code>List&lt;Object&gt;</code> 能接收 <code>List&lt;String&gt;</code> 吗？」→ 不能，泛型不变（invariant），<code>List&lt;String&gt;</code> 不是 <code>List&lt;Object&gt;</code> 的子类型；需要协变用 <code>List&lt;? extends Object&gt;</code>。</li><li>「泛型数组为什么不能 new？」→ <code>new T[]</code>、<code>new List&lt;String&gt;[]</code> 编译错误，因擦除后无法保证类型安全；用 <code>(T[]) new Object[n]</code> 或集合替代。</li></ul><h3 id="易错点-7" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-7" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li>泛型不支持基本类型（<code>List&lt;int&gt;</code> 非法，用 <code>List&lt;Integer&gt;</code>）。</li><li>静态方法/静态字段不能使用类的泛型类型参数（泛型参数属于实例）。</li></ul><hr><h2 id="反射机制、获取-class-的几种方式、优缺点-★★★" tabindex="-1">反射机制、获取 Class 的几种方式、优缺点 ★★★ <a class="header-anchor" href="#反射机制、获取-class-的几种方式、优缺点-★★★" aria-label="Permalink to &quot;反射机制、获取 Class 的几种方式、优缺点 ★★★&quot;">​</a></h2><h3 id="是什么-2" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-2" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><ul><li>反射：运行期动态获取类的结构信息（构造器、字段、方法、注解）并调用，突破编译期类型检查。</li></ul><h3 id="获取-class-对象的方式" tabindex="-1">获取 Class 对象的方式 <a class="header-anchor" href="#获取-class-对象的方式" aria-label="Permalink to &quot;获取 Class 对象的方式&quot;">​</a></h3><ul><li><code>类名.class</code>（编译期已知，最常用，不触发初始化）。</li><li><code>对象.getClass()</code>（已有对象）。</li><li><code>Class.forName(&quot;全限定名&quot;)</code>（会触发类初始化）。</li><li><code>类加载器.loadClass(&quot;全限定名&quot;)</code>（不触发初始化）。</li></ul><h3 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h3><ul><li>框架底层：Spring 通过反射实例化 Bean、注入依赖；MyBatis 通过反射做结果映射；JUnit 运行测试方法；动态代理。</li></ul><h3 id="优点-缺点" tabindex="-1">优点 / 缺点 <a class="header-anchor" href="#优点-缺点" aria-label="Permalink to &quot;优点 / 缺点&quot;">​</a></h3><ul><li>优点：动态、灵活，能编写通用框架。</li><li>缺点：① 绕过编译检查，运行时才暴露错误；② 性能较低（可缓存 Method/Field/Constructor 缓解）；③ 破坏封装，可访问 private 成员（<code>setAccessible(true)</code>）。</li></ul><h3 id="追问应对-8" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-8" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「反射性能为什么慢？怎么优化？」→ 慢在动态解析 + 安全检查 + 自动装箱；优化：缓存反射对象、<code>setAccessible(true)</code> 关闭安全检查、用 MethodHandle 或代码生成（如 CGLIB）替代频繁反射。</li></ul><h3 id="易错点-8" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-8" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li><code>Class.forName</code> 会触发静态初始化（执行 static 块），<code>loadClass</code> 不会——JDBC 驱动加载就用 <code>Class.forName</code> 触发驱动注册。</li></ul><hr><h2 id="注解、元注解、自定义注解-★★☆" tabindex="-1">注解、元注解、自定义注解 ★★☆ <a class="header-anchor" href="#注解、元注解、自定义注解-★★☆" aria-label="Permalink to &quot;注解、元注解、自定义注解 ★★☆&quot;">​</a></h2><h3 id="是什么-3" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-3" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><ul><li>注解是给代码附加元数据的标记，本身不改变逻辑，需通过反射（运行期）或注解处理器（编译期）读取生效。</li></ul><h3 id="元注解" tabindex="-1">元注解 <a class="header-anchor" href="#元注解" aria-label="Permalink to &quot;元注解&quot;">​</a></h3><ul><li><code>@Target</code>：作用范围（TYPE/METHOD/FIELD/PARAMETER 等）。</li><li><code>@Retention</code>：保留级别 SOURCE（源码，编译丢弃）、CLASS（字节码，默认）、RUNTIME（运行期可反射读取）。</li><li><code>@Documented</code>：写入 javadoc。</li><li><code>@Inherited</code>：子类继承父类注解（只对类注解有效）。</li><li>JDK8 新增 <code>@Repeatable</code>（可重复注解）。</li></ul><h3 id="自定义注解" tabindex="-1">自定义注解 <a class="header-anchor" href="#自定义注解" aria-label="Permalink to &quot;自定义注解&quot;">​</a></h3><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#E1E4E8;">@</span><span style="color:#F97583;">Target</span><span style="color:#E1E4E8;">(ElementType.METHOD)</span></span>
<span class="line"><span style="color:#E1E4E8;">@</span><span style="color:#F97583;">Retention</span><span style="color:#E1E4E8;">(RetentionPolicy.RUNTIME)</span></span>
<span class="line"><span style="color:#F97583;">public</span><span style="color:#E1E4E8;"> @</span><span style="color:#F97583;">interface</span><span style="color:#E1E4E8;"> </span><span style="color:#F97583;">MyLog</span><span style="color:#E1E4E8;"> {</span></span>
<span class="line"><span style="color:#E1E4E8;">    String </span><span style="color:#B392F0;">value</span><span style="color:#E1E4E8;">() </span><span style="color:#F97583;">default</span><span style="color:#E1E4E8;"> </span><span style="color:#9ECBFF;">&quot;&quot;</span><span style="color:#E1E4E8;">;</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292E;">@</span><span style="color:#D73A49;">Target</span><span style="color:#24292E;">(ElementType.METHOD)</span></span>
<span class="line"><span style="color:#24292E;">@</span><span style="color:#D73A49;">Retention</span><span style="color:#24292E;">(RetentionPolicy.RUNTIME)</span></span>
<span class="line"><span style="color:#D73A49;">public</span><span style="color:#24292E;"> @</span><span style="color:#D73A49;">interface</span><span style="color:#24292E;"> </span><span style="color:#D73A49;">MyLog</span><span style="color:#24292E;"> {</span></span>
<span class="line"><span style="color:#24292E;">    String </span><span style="color:#6F42C1;">value</span><span style="color:#24292E;">() </span><span style="color:#D73A49;">default</span><span style="color:#24292E;"> </span><span style="color:#032F62;">&quot;&quot;</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><ul><li>解析：运行期 <code>method.getAnnotation(MyLog.class)</code>；编译期用 APT（注解处理器，如 Lombok 生成代码）。</li></ul><h3 id="追问应对-9" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-9" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「注解怎么生效的？」→ 分两种：RUNTIME 注解靠反射读取；SOURCE/CLASS 注解靠编译期注解处理器（Lombok 就是 APT 在编译期改字节码）。</li></ul><hr><h2 id="bio-nio-aio-buffer、channel、selector-★★★" tabindex="-1">BIO / NIO / AIO；Buffer、Channel、Selector ★★★ <a class="header-anchor" href="#bio-nio-aio-buffer、channel、selector-★★★" aria-label="Permalink to &quot;BIO / NIO / AIO；Buffer、Channel、Selector ★★★&quot;">​</a></h2><h3 id="三模型" tabindex="-1">三模型 <a class="header-anchor" href="#三模型" aria-label="Permalink to &quot;三模型&quot;">​</a></h3><ul><li>BIO（同步阻塞）：一连接一线程，读写阻塞，线程开销大，不适合高并发。</li><li>NIO（同步非阻塞）：Selector 多路复用，一个线程管理多个连接，连接有事件才处理，适合高并发。</li><li>AIO（异步非阻塞）：读写完成回调通知，不主动轮询，Java7 引入。</li></ul><h3 id="nio-三大组件" tabindex="-1">NIO 三大组件 <a class="header-anchor" href="#nio-三大组件" aria-label="Permalink to &quot;NIO 三大组件&quot;">​</a></h3><ul><li>Buffer：缓冲区（capacity 容量、position 当前读写位置、limit 上限），读写通过 flip/clear 切换。</li><li>Channel：双向通道（FileChannel、SocketChannel、ServerSocketChannel），可读可写。</li><li>Selector：多路复用器，注册多个 Channel，监听 OP_READ/OP_WRITE/OP_ACCEPT/OP_CONNECT 就绪事件。</li></ul><h3 id="底层原理" tabindex="-1">底层原理 <a class="header-anchor" href="#底层原理" aria-label="Permalink to &quot;底层原理&quot;">​</a></h3><ul><li>NIO 依赖操作系统的 IO 多路复用（Linux 的 select/poll/epoll），epoll 事件驱动、O(1) 获取就绪连接，Netty 就是基于 NIO 封装。</li></ul><h3 id="追问应对-10" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-10" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「Netty 为什么用 NIO 不用 BIO/AIO？」→ NIO 多路复用适合高并发长连接；AIO 在 Linux 实现不成熟（底层仍是 epoll 模拟），跨平台一致性和性能不如 NIO。</li></ul><h3 id="易错点-9" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-9" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li>BIO 的「阻塞」是线程阻塞在 read/write；NIO 的「非阻塞」是线程不阻塞在单个连接，而是轮询就绪事件。</li></ul><hr><h2 id="与-equals、hashcode-契约-★★★" tabindex="-1">== 与 equals、hashCode 契约 ★★★ <a class="header-anchor" href="#与-equals、hashcode-契约-★★★" aria-label="Permalink to &quot;== 与 equals、hashCode 契约 ★★★&quot;">​</a></h2><h3 id="是什么-4" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-4" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><ul><li><code>==</code>：比较基本类型的「值」，或引用类型的「内存地址」。</li><li><code>equals</code>：Object 默认也是比较地址（等价 <code>==</code>），String/Integer 等重写为「值比较」。</li><li><code>hashCode</code>：返回对象哈希码，用于 HashMap/HashSet 定位桶。</li></ul><h3 id="契约-重点" tabindex="-1">契约（重点） <a class="header-anchor" href="#契约-重点" aria-label="Permalink to &quot;契约（重点）&quot;">​</a></h3><ol><li>重写 equals 必须重写 hashCode（相等对象的 hashCode 必须相等）。</li><li>两个对象 equals 相等 → hashCode 必须相等（单向，反过来不成立：hashCode 相等不代表 equals 相等，即哈希碰撞）。</li></ol><ul><li>违反后果：对象放入 HashSet/HashMap 后，若只重写 equals 不重写 hashCode，两个 equals 相等的对象 hashCode 不同，会落到不同桶，<code>contains</code>/<code>get</code> 找不到，出现「相同对象能重复加入」的 bug。</li></ul><h3 id="追问应对-11" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-11" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么 hashCode 冲突是允许的？」→ 哈希表本身就有碰撞，靠链表/红黑树解决；只要 equals 相等 hash 一致即可。</li></ul><h3 id="易错点-10" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-10" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li>equals 要满足自反、对称、传递、一致、非空（对 null 返回 false）。</li></ul><hr><h2 id="深拷贝与浅拷贝、序列化-serialversionuid-★★☆" tabindex="-1">深拷贝与浅拷贝、序列化 serialVersionUID ★★☆ <a class="header-anchor" href="#深拷贝与浅拷贝、序列化-serialversionuid-★★☆" aria-label="Permalink to &quot;深拷贝与浅拷贝、序列化 serialVersionUID ★★☆&quot;">​</a></h2><h3 id="是什么-5" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-5" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><ul><li>浅拷贝：只复制对象本身，其内部引用类型字段仍指向原对象（共享）。</li><li>深拷贝：对象及其引用链上的对象全部独立复制。</li></ul><h3 id="实现" tabindex="-1">实现 <a class="header-anchor" href="#实现" aria-label="Permalink to &quot;实现&quot;">​</a></h3><ul><li>浅拷贝：实现 <code>Cloneable</code> + 覆写 <code>clone()</code>（<code>super.clone()</code> 是浅拷贝）。</li><li>深拷贝：① 递归 clone 内部对象；② 序列化 + 反序列化（对象及内部对象都需 Serializable）；③ 手动 new 复制。</li></ul><h3 id="serialversionuid" tabindex="-1">serialVersionUID <a class="header-anchor" href="#serialversionuid" aria-label="Permalink to &quot;serialVersionUID&quot;">​</a></h3><ul><li>序列化版本号；不显式声明时 JVM 根据类结构自动生成，类结构一变（加字段/方法）生成值改变，反序列化旧数据会抛 <code>InvalidClassException</code>。</li><li>显式声明 <code>private static final long serialVersionUID = 1L;</code> 保证兼容。</li></ul><h3 id="追问应对-12" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-12" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「transient 关键字作用？」→ 标记字段不参与序列化；反序列化后为默认值；常用于敏感信息（密码）或不可序列化字段。</li><li>「序列化怎么破坏单例？」→ 反序列化会 new 新对象绕过单例构造器；解决：单例类加 <code>readResolve()</code> 返回已有实例。</li></ul><hr><h2 id="bigdecimal-与浮点精度-★★★" tabindex="-1">BigDecimal 与浮点精度 ★★★ <a class="header-anchor" href="#bigdecimal-与浮点精度-★★★" aria-label="Permalink to &quot;BigDecimal 与浮点精度 ★★★&quot;">​</a></h2><h3 id="为什么-float-double-有精度问题" tabindex="-1">为什么 float/double 有精度问题 <a class="header-anchor" href="#为什么-float-double-有精度问题" aria-label="Permalink to &quot;为什么 float/double 有精度问题&quot;">​</a></h3><ul><li>二进制无法精确表示部分十进制小数（如 0.1 是无限循环二进制），运算产生舍入误差。金额计算必须用 BigDecimal。</li></ul><h3 id="bigdecimal-用法" tabindex="-1">BigDecimal 用法 <a class="header-anchor" href="#bigdecimal-用法" aria-label="Permalink to &quot;BigDecimal 用法&quot;">​</a></h3><ul><li>构造必须用字符串：<code>new BigDecimal(&quot;0.1&quot;)</code>，不能用 <code>new BigDecimal(0.1)</code>（double 已失真）。</li><li>运算用 <code>add/subtract/multiply/divide</code>，<code>divide</code> 必须指定 <code>RoundingMode</code> 或精度，否则除不尽抛 ArithmeticException。</li><li>比较用 <code>compareTo</code>（比较数值，忽略 scale），不能用 <code>equals</code>（equals 会比较 scale，<code>0.1</code> 与 <code>0.10</code> 的 equals 为 false）。</li></ul><h3 id="追问应对-13" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-13" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么 0.1+0.2 != 0.3？」→ 二进制浮点表示误差，0.1 和 0.2 存储时就是近似值。</li></ul><h3 id="易错点-11" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-11" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li><code>BigDecimal</code> 是不可变对象，运算后必须接返回值（<code>a.add(b)</code> 不会改 a）。</li><li>金额通常存 <code>long</code>（分）或 <code>Decimal</code> 类型，避免浮点。</li></ul><hr><h2 id="四种内部类-★☆☆" tabindex="-1">四种内部类 ★☆☆ <a class="header-anchor" href="#四种内部类-★☆☆" aria-label="Permalink to &quot;四种内部类 ★☆☆&quot;">​</a></h2><ul><li>成员内部类：可访问外部类所有成员；持有外部类引用（<code>Outer.this</code>）。</li><li>静态内部类（static nested class）：不依赖外部实例，只能访问外部静态成员；最常用（如 Builder 模式、静态工具）。</li><li>局部内部类：定义在方法内，作用域仅方法内。</li><li>匿名内部类：一次性实现，<code>new Runnable(){...}</code>；只能访问 final 或 effectively final 的局部变量（JDK8 起不强制 final，但要求不被修改）。</li></ul><h3 id="追问应对-14" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-14" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「匿名内部类为什么要求局部变量 effectively final？」→ 内部类持有的是变量副本，若变量可变，副本与原始变量会不一致，故语言强制其不变以保证语义一致。</li></ul><hr><h2 id="枚举原理-★★☆" tabindex="-1">枚举原理 ★★☆ <a class="header-anchor" href="#枚举原理-★★☆" aria-label="Permalink to &quot;枚举原理 ★★☆&quot;">​</a></h2><h3 id="是什么-6" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-6" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><ul><li>enum 本质是继承 <code>java.lang.Enum</code> 的 final 类，每个枚举常量是 <code>public static final</code> 的实例，构造器私有。</li><li>可定义字段、构造器、方法、实现接口。</li></ul><h3 id="为什么枚举是安全的单例" tabindex="-1">为什么枚举是安全的单例 <a class="header-anchor" href="#为什么枚举是安全的单例" aria-label="Permalink to &quot;为什么枚举是安全的单例&quot;">​</a></h3><ul><li>JVM 保证枚举实例在类加载时创建且唯一，且能天然防反射（反射 newInstance 会抛异常）和防序列化破坏（反序列化返回同一实例）。所以《Effective Java》推荐枚举实现单例。</li></ul><h3 id="追问应对-15" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-15" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「枚举和普通类区别？」→ 继承 Enum、实例固定且唯一、不能继承其他类、可比较（ordinal）、自带 name()/values()/valueOf()。</li></ul><hr><h2 id="函数式接口、lambda、stream-★★★" tabindex="-1">函数式接口、Lambda、Stream ★★★ <a class="header-anchor" href="#函数式接口、lambda、stream-★★★" aria-label="Permalink to &quot;函数式接口、Lambda、Stream ★★★&quot;">​</a></h2><h3 id="函数式接口" tabindex="-1">函数式接口 <a class="header-anchor" href="#函数式接口" aria-label="Permalink to &quot;函数式接口&quot;">​</a></h3><ul><li>仅一个抽象方法的接口，可用 <code>@FunctionalInterface</code> 标注（编译器强制检查）。</li><li>常见：<code>Function&lt;T,R&gt;</code>（转换）、<code>Predicate&lt;T&gt;</code>（断言）、<code>Consumer&lt;T&gt;</code>（消费）、<code>Supplier&lt;T&gt;</code>（提供）、<code>BiFunction</code> 等。</li></ul><h3 id="lambda" tabindex="-1">Lambda <a class="header-anchor" href="#lambda" aria-label="Permalink to &quot;Lambda&quot;">​</a></h3><ul><li>函数式接口的简洁实现：<code>(参数) -&gt; 表达式</code>；本质是编译成 <code>invokedynamic</code> 生成函数式接口实现（JDK8 用 LambdaMetafactory，非匿名内部类，无额外 class 文件）。</li></ul><h3 id="stream" tabindex="-1">Stream <a class="header-anchor" href="#stream" aria-label="Permalink to &quot;Stream&quot;">​</a></h3><ul><li>三部分：数据源 → 中间操作（惰性，不立即执行）→ 终结操作（触发执行）。</li><li>中间操作：filter/map/sorted/distinct/limit/skip；终结操作：collect/forEach/reduce/count/anyMatch。</li><li>惰性求值：没有终结操作时中间操作不执行。</li></ul><h3 id="追问应对-16" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-16" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「Stream 和循环区别？」→ Stream 声明式、可链式、可并行（<code>parallelStream</code>），但注意并行流用共享线程池 ForkJoinPool，不适合有状态/阻塞操作。</li><li>「map 和 flatMap 区别？」→ map 一对一转换；flatMap 一对多，把嵌套流拍平（如 <code>List&lt;List&lt;T&gt;&gt;</code> 转 <code>List&lt;T&gt;</code>）。</li></ul><h3 id="易错点-12" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-12" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li>Stream 只能消费一次，重复使用报 IllegalStateException。</li><li><code>parallelStream</code> 在低并发小数据量下可能比串行还慢（线程调度开销）。</li></ul><hr><h2 id="值传递与引用传递-前端转全栈必考-★★★" tabindex="-1">值传递与引用传递（前端转全栈必考）★★★ <a class="header-anchor" href="#值传递与引用传递-前端转全栈必考-★★★" aria-label="Permalink to &quot;值传递与引用传递（前端转全栈必考）★★★&quot;">​</a></h2><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><ul><li>Java 只有「值传递」，没有引用传递： <ul><li>基本类型：传「值的副本」，方法内改参数不影响外部。</li><li>引用类型：传「引用（地址）的副本」，副本和原引用指向同一个对象，所以方法内修改「对象内容」会影响外部；但修改「引用本身」（重新 new / 指向别的对象）不影响外部引用。</li></ul></li></ul><h3 id="经典例子" tabindex="-1">经典例子 <a class="header-anchor" href="#经典例子" aria-label="Permalink to &quot;经典例子&quot;">​</a></h3><ul><li><code>swap(a, b)</code> 交换两个对象引用，方法外不会真正交换，因为改的是副本引用。</li><li>方法内 <code>obj.field = x</code>（改内容）→ 外部可见；方法内 <code>obj = new X()</code>（改引用）→ 外部不可见。</li></ul><h3 id="与-js-对比" tabindex="-1">与 JS 对比 <a class="header-anchor" href="#与-js-对比" aria-label="Permalink to &quot;与 JS 对比&quot;">​</a></h3><ul><li>JS 对 primitive 也是按值、对 object 是传「引用副本」，行为一致；差别是 Java 面试强调「只有值传递」这个结论，常让人辨析。</li></ul><h3 id="追问应对-17" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-17" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「为什么说 Java 只有值传递？」→ 因为无论基本类型还是引用，传入的都是「副本」；引用传递的含义是「方法能拿到调用者的变量本身并修改它指向」，Java 做不到。</li></ul><h3 id="易错点-13" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-13" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li>别被「引用类型传的是引用」误导成「引用传递」；区分「传的是引用副本」和「传引用（可改原引用指向）」。</li></ul><hr><h2 id="final、finally、finalize-区别-★★★" tabindex="-1">final、finally、finalize 区别 ★★★ <a class="header-anchor" href="#final、finally、finalize-区别-★★★" aria-label="Permalink to &quot;final、finally、finalize 区别 ★★★&quot;">​</a></h2><h3 id="final" tabindex="-1">final <a class="header-anchor" href="#final" aria-label="Permalink to &quot;final&quot;">​</a></h3><ul><li>修饰类：不能被继承；修饰方法：不能被重写；修饰变量：基本类型值不可变、引用类型引用不可变（但指向的对象内容可变）。</li><li>final 变量修饰引用时，引用不能重新赋值，但 <code>obj.field</code> 仍可改。</li></ul><h3 id="finally" tabindex="-1">finally <a class="header-anchor" href="#finally" aria-label="Permalink to &quot;finally&quot;">​</a></h3><ul><li>异常处理关键字，无论是否抛异常都执行（除非 System.exit / 线程被 kill）；常考 finally 中 return 覆盖 try 的 return。</li></ul><h3 id="finalize" tabindex="-1">finalize <a class="header-anchor" href="#finalize" aria-label="Permalink to &quot;finalize&quot;">​</a></h3><ul><li>Object 的方法，对象被 GC 回收前调用一次；JDK9 起废弃（执行时机不确定、可能复活对象、性能差），替代方案是 Cleaner 或 try-with-resources。</li></ul><h3 id="追问应对-18" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-18" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「final 和 finally 有关系吗？」→ 无，只是拼写相似。</li><li>「finalize 为什么废弃？」→ 触发时机不确定、可能延迟 GC、甚至复活对象导致二次回收，建议显式释放资源。</li></ul><hr><h2 id="object-类常用方法-★★☆" tabindex="-1">Object 类常用方法 ★★☆ <a class="header-anchor" href="#object-类常用方法-★★☆" aria-label="Permalink to &quot;Object 类常用方法 ★★☆&quot;">​</a></h2><ul><li><code>equals</code>、<code>hashCode</code>（成对重写，见契约）、<code>toString</code>（建议重写便于日志）、<code>clone</code>（需实现 Cloneable）、<code>getClass</code>（获取 Class，final 不可覆写）、<code>finalize</code>（废弃）。</li><li>线程相关：<code>wait()</code>、<code>notify()</code>、<code>notifyAll()</code>（用于线程协作，见多线程篇）。</li><li>追问：「Object 有哪些方法？」→ 上述 9 个 + <code>registerNatives</code>（native 方法注册）。</li></ul><hr><h2 id="类初始化顺序、静态变量-代码块-★★☆" tabindex="-1">类初始化顺序、静态变量/代码块 ★★☆ <a class="header-anchor" href="#类初始化顺序、静态变量-代码块-★★☆" aria-label="Permalink to &quot;类初始化顺序、静态变量/代码块 ★★☆&quot;">​</a></h2><h3 id="顺序" tabindex="-1">顺序 <a class="header-anchor" href="#顺序" aria-label="Permalink to &quot;顺序&quot;">​</a></h3><ol><li>父类静态变量 / 静态代码块（按书写顺序）。</li><li>子类静态变量 / 静态代码块。</li><li>父类实例变量 / 实例代码块 / 构造器。</li><li>子类实例变量 / 实例代码块 / 构造器。</li></ol><h3 id="关键" tabindex="-1">关键 <a class="header-anchor" href="#关键" aria-label="Permalink to &quot;关键&quot;">​</a></h3><ul><li>静态变量和静态块只在类「首次被主动使用」时执行一次（类加载的初始化阶段）。</li><li>实例代码块每次 new 都执行，且在构造器之前。</li><li>同类内部按书写顺序执行，构造器最后。</li></ul><h3 id="触发类初始化的时机-主动引用" tabindex="-1">触发类初始化的时机（主动引用） <a class="header-anchor" href="#触发类初始化的时机-主动引用" aria-label="Permalink to &quot;触发类初始化的时机（主动引用）&quot;">​</a></h3><ul><li>new 对象、访问类的静态变量/静态方法、反射（Class.forName）、初始化子类先初始化父类、main 所在类。</li><li>被动引用不触发初始化：通过子类访问父类静态变量（只初始化父类）、引用常量（编译期已入常量池）、定义数组。</li></ul><h3 id="易错点-14" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-14" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li>「<code>new 子类</code> 会初始化父类吗？」→ 会，先父后子。</li></ul><hr><h2 id="comparable-与-comparator-区别-★★☆" tabindex="-1">Comparable 与 Comparator 区别 ★★☆ <a class="header-anchor" href="#comparable-与-comparator-区别-★★☆" aria-label="Permalink to &quot;Comparable 与 Comparator 区别 ★★☆&quot;">​</a></h2><ul><li>Comparable（内部比较器）：类实现 <code>compareTo(o)</code>，定义「自然排序」，侵入类内部，只能一种排序。</li><li>Comparator（外部比较器）：实现 <code>compare(a, b)</code>，不改原类，可定义多种排序；常配合 lambda <code>Comparator.comparing(...).thenComparing(...)</code>。</li><li>用法：<code>Collections.sort(list, comparator)</code>、<code>stream().sorted(comparator)</code>；TreeSet/TreeMap 依赖它们。</li></ul><h3 id="追问应对-19" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-19" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「什么时候用哪个？」→ 一种自然顺序用 Comparable；多种/临时/外部排序规则用 Comparator；Comparator 更灵活，优先用。</li></ul><hr><h2 id="java-8-新特性汇总、optional-★★★" tabindex="-1">Java 8 新特性汇总、Optional ★★★ <a class="header-anchor" href="#java-8-新特性汇总、optional-★★★" aria-label="Permalink to &quot;Java 8 新特性汇总、Optional ★★★&quot;">​</a></h2><h3 id="新特性" tabindex="-1">新特性 <a class="header-anchor" href="#新特性" aria-label="Permalink to &quot;新特性&quot;">​</a></h3><ul><li>Lambda、函数式接口、方法引用（<code>::</code>）、Stream、Optional、新时间 API（LocalDate/LocalDateTime/Instant/DateTimeFormatter）、接口 default/static 方法、CompletableFuture、Base64、可重复注解、方法参数反射。</li></ul><h3 id="optional-★★★" tabindex="-1">Optional ★★★ <a class="header-anchor" href="#optional-★★★" aria-label="Permalink to &quot;Optional ★★★&quot;">​</a></h3><ul><li>用途：包装可能为 null 的值，显式表达「可能为空」，避免 NPE。</li><li>创建：<code>of</code>（值不能 null）、<code>ofNullable</code>、<code>empty</code>。</li><li>判断执行：<code>isPresent</code>、<code>ifPresent</code>。</li><li>兜底：<code>orElse</code>（惰性求值用 <code>orElseGet</code>）、<code>orElseThrow</code>。</li><li>转换：<code>map</code>、<code>flatMap</code>。</li><li>注意：<code>orElse</code> 无论值是否存在都计算参数（<code>orElse(expensive())</code> 会先算 expensive），<code>orElseGet</code> 才惰性。</li><li>最佳实践：Optional 只作方法返回值，不作字段、不作方法参数、不用于集合元素（会增加装箱开销）。</li></ul><h3 id="易错点-15" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-15" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li><code>Optional.get()</code> 在 empty 时抛 NoSuchElementException，应先判断或 orElse 兜底。</li></ul><hr><h2 id="集合框架选型总结-★★★" tabindex="-1">集合框架选型总结 ★★★ <a class="header-anchor" href="#集合框架选型总结-★★★" aria-label="Permalink to &quot;集合框架选型总结 ★★★&quot;">​</a></h2><ul><li>List：有序可重复 → 读多 ArrayList，频繁头尾/队列栈 LinkedList。</li><li>Set：去重 → HashSet（无序 O(1)）、LinkedHashSet（保持插入顺序）、TreeSet（排序）。</li><li>Map：HashMap（无序）、LinkedHashMap（保持插入顺序，可做 LRU）、TreeMap（按 key 排序）、ConcurrentHashMap（并发）。</li><li>线程安全：ConcurrentHashMap、CopyOnWriteArrayList，或 <code>Collections.synchronizedXxx</code> 包装。</li></ul><h3 id="追问应对-20" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-20" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「LinkedHashMap 怎么实现 LRU？」→ 继承 LinkedHashMap 重写 <code>removeEldestEntry</code>，accessOrder=true 时访问过的元素移到尾部，超出容量删最老元素。</li></ul><hr><h2 id="fail-fast-与-fail-safe-★★☆" tabindex="-1">fail-fast 与 fail-safe ★★☆ <a class="header-anchor" href="#fail-fast-与-fail-safe-★★☆" aria-label="Permalink to &quot;fail-fast 与 fail-safe ★★☆&quot;">​</a></h2><h3 id="是什么-7" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-7" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><ul><li>fail-fast（快速失败）：遍历时用 modCount 检测并发修改，结构一变立即抛 ConcurrentModificationException；ArrayList/HashMap 的迭代器属于此类。</li><li>fail-safe（安全失败）：遍历的是副本（快照），修改不影响遍历、不抛异常；CopyOnWriteArrayList、ConcurrentHashMap 属于此类。</li></ul><h3 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h3><ul><li>fail-fast：集合有 <code>modCount</code>（结构修改计数器），迭代器创建时记录期望值，每次 <code>next()</code> 前校验，不一致即抛异常。</li><li>fail-safe：CopyOnWriteArrayList 的迭代器遍历的是写时复制的旧数组快照。</li></ul><h3 id="易错点-16" tabindex="-1">易错点 <a class="header-anchor" href="#易错点-16" aria-label="Permalink to &quot;易错点&quot;">​</a></h3><ul><li><code>for-each</code> 里调 <code>list.remove()</code> 抛 ConcurrentModificationException；正确做法 <code>iterator.remove()</code> 或 <code>removeIf</code>。</li><li>fail-safe 读到的可能是「旧数据」（弱一致）。</li></ul><hr><h2 id="jdk-版本演进-8-11-17-21-新特性-★★☆" tabindex="-1">JDK 版本演进：8 / 11 / 17 / 21 新特性 ★★☆ <a class="header-anchor" href="#jdk-版本演进-8-11-17-21-新特性-★★☆" aria-label="Permalink to &quot;JDK 版本演进：8 / 11 / 17 / 21 新特性 ★★☆&quot;">​</a></h2><ul><li>Java 8（LTS）：Lambda、Stream、Optional、新时间 API、接口 default/static（最重要，绝大多数项目基线）。</li><li>Java 11（LTS）：var 局部变量类型推断、HTTP Client API、String 增强（isBlank/lines/strip）、单文件运行。</li><li>Java 17（LTS）：sealed 类、switch 表达式增强、record 记录类、文本块（<code>&quot;&quot;&quot;...&quot;&quot;&quot;</code>）、instanceof 模式匹配。</li><li>Java 21（LTS，重点）： <ul><li><strong>虚拟线程</strong>（Virtual Thread）：轻量级线程，JVM 调度，可百万级并发。</li><li>结构化并发、ScopedValue（虚拟线程中替代 ThreadLocal 传递）。</li><li>记录模式匹配、switch 模式匹配、字符串模板（预览）。</li></ul></li></ul><h3 id="追问应对-21" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-21" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「record 是什么？」→ 不可变数据载体，自动生成构造器/getter/equals/hashCode/toString，替代繁琐 POJO。</li><li>「sealed 类？」→ 限制哪些类能继承/实现它，增强类型安全与模式匹配穷尽性。</li></ul><hr><h2 id="虚拟线程-vs-平台线程-★★☆" tabindex="-1">虚拟线程 vs 平台线程 ★★☆ <a class="header-anchor" href="#虚拟线程-vs-平台线程-★★☆" aria-label="Permalink to &quot;虚拟线程 vs 平台线程 ★★☆&quot;">​</a></h2><h3 id="是什么-8" tabindex="-1">是什么 <a class="header-anchor" href="#是什么-8" aria-label="Permalink to &quot;是什么&quot;">​</a></h3><ul><li>平台线程（传统 Thread）：1:1 映射 OS 线程，创建/切换成本高、数量有限（几百到几千），IO 阻塞会占住线程。</li><li>虚拟线程：M:N 映射到少量载体线程（OS 线程），由 JVM 调度；IO 阻塞时 JVM 自动挂起该虚拟线程并切换执行其他虚拟线程，创建成本极低，支持百万级并发。</li></ul><h3 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h3><ul><li>适合 IO 密集型、高并发（Web 请求处理、大量下游/DB 调用）。</li><li>不适合 CPU 密集计算（无收益，甚至增加调度开销）。</li></ul><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h3><ul><li><code>Thread.ofVirtual().start(task)</code> 或 <code>Executors.newVirtualThreadPerTaskExecutor()</code>（每任务一虚拟线程，无需大线程池）。</li></ul><h3 id="追问应对-22" tabindex="-1">追问应对 <a class="header-anchor" href="#追问应对-22" aria-label="Permalink to &quot;追问应对&quot;">​</a></h3><ul><li>「虚拟线程会取代线程池吗？」→ 虚拟线程场景下不再需要为「每请求一线程」配置庞大线程池，但 CPU 密集或需要限流/隔离的场景仍会配合信号量/线程池使用。</li><li>「为什么 IO 密集用虚拟线程收益大？」→ 传统线程阻塞在 IO 时 OS 线程被占住，无法复用；虚拟线程阻塞时载体线程可立即切走执行其他任务，吞吐大幅提升。</li></ul>`,280)]))}const b=e(t,[["render",r]]);export{p as __pageData,b as default};
